import re

def gitignore_match(pattern, path):
    dir_only = False
    if pattern.endswith('/'):
        dir_only = True
        pattern = pattern[:-1]

    is_dir = path.endswith('/')
    if is_dir:
        path = path[:-1]

    if dir_only and not is_dir:
        return False

    anchored = False
    if pattern.startswith('/'):
        pattern = pattern[1:]
        anchored = True
    elif '/' in pattern:
        anchored = True

    regex_parts = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '*':
            if i + 1 < n and pattern[i+1] == '*':
                if i + 2 < n and pattern[i+2] == '/':
                    regex_parts.append('(?:.*/)?')
                    i += 3
                elif i == n - 2:
                    regex_parts.append('.*')
                    i += 2
                else:
                    regex_parts.append('(?:.*/)?')
                    i += 2
            else:
                regex_parts.append('[^/]*')
                i += 1
        elif c == '?':
            regex_parts.append('[^/]')
            i += 1
        elif c == '[':
            j = i + 1
            if j < n and pattern[j] in ('!', '^'):
                j += 1
            if j < n and pattern[j] == ']':
                j += 1
            while j < n and pattern[j] != ']':
                j += 1
            if j >= n:
                regex_parts.append(re.escape(c))
                i += 1
            else:
                cls = pattern[i+1:j]
                if '/' in cls:
                    cls = cls.replace('/', '[^/]')
                regex_parts.append('[' + cls + ']')
                i = j + 1
        elif c == '/':
            regex_parts.append('/')
            i += 1
        else:
            regex_parts.append(re.escape(c))
            i += 1

    regex_str = ''.join(regex_parts)

    if anchored:
        full_regex = '^' + regex_str + '$'
    else:
        full_regex = '(?:.*/)?' + regex_str + '$'

    return bool(re.match(full_regex, path))
