def parse_range(header, size):
    header = header.strip()
    if not header.startswith('bytes='):
        return None

    range_set = header[6:]
    ranges = []

    for spec in range_set.split(','):
        spec = spec.strip()
        if not spec:
            continue

        if spec.startswith('-'):
            try:
                suffix_len = int(spec[1:])
            except ValueError:
                return None

            if suffix_len <= 0:
                return None

            start = size - suffix_len if suffix_len <= size else 0
            end = size - 1
            ranges.append((start, end))
        else:
            parts = spec.split('-', 1)
            try:
                first = int(parts[0])
            except ValueError:
                return None

            if first < 0:
                return None

            if len(parts) == 2:
                if parts[1] == '':
                    last = size - 1
                else:
                    try:
                        last = int(parts[1])
                    except ValueError:
                        return None

                    if last < first:
                        return None
            else:
                last = size - 1

            if first >= size:
                continue

            if last > size - 1:
                last = size - 1

            ranges.append((first, last))

    return ranges if ranges else None

