import heapq

def topk(stream, k):
    heap = []
    for i, (val, lab) in enumerate(stream):
        heapq.heappush(heap, (val, -i, lab))
        if len(heap) > k:
            heapq.heappop(heap)
    return [(v, l) for v, _, l in sorted(heap, key=lambda x: (-x[0], -x[1]))]
