                    except ValueError:
                        raise ValueError(f"Invalid range: {base}")
                    start, end = a, b
                else:
                    try:
                        start = int(base)
                    except ValueError:
                        raise ValueError(f"Invalid number: {base}")
                    end = max_val

                if start > end:
                    raise ValueError("Start must be <= end in range")
                for v in range(start, end + 1, step):
                    values.add(v)
            elif '-' in part:
                try:
                    a, b = map(int, part.split('-', 1))
                except ValueError:
                    raise ValueError(f"Invalid range: {part}")
                if a > b:
                    raise ValueError("Start must be <= end")
                for v in range(a, b + 1):
                    values.add(v)
            elif part == '*':
                values.update(range(min_val, max_val + 1))
            else:
                try:
                    v = int(part)
                except ValueError:
                    raise ValueError(f"Invalid value: {part}")
                values.add(v)

        for v in values:
            if not (min_val <= v <= max_val):
                raise ValueError(f"Value {v} out of range [{min_val}, {max_val}]")
