def wildcard_match(pattern, s):
    i = j = star_i = star_j = -1
    m, n = len(pattern), len(s)

    while j < n:
        if i < m and (pattern[i] == '?' or pattern[i] == s[j]):
            i += 1
            j += 1
        elif i < m and pattern[i] == '*':
            star_i, star_j = i, j
            i += 1
        elif star_i != -1:
            i = star_i + 1
            star_j += 1
            j = star_j
        else:
            return False

    while i < m and pattern[i] == '*':
        i += 1

    return i == m
