def window_medians(a, k):
    if not a or k > len(a):
        return []

    lo = []
    hi = []
    to_remove_lo = {}
    to_remove_hi = {}
    balance = 0

    res = []

    for i, x in enumerate(a):
        heapq.heappush(lo, -x)
        balance += 1

        if i >= k:
            out_val = a[i-k]
            while lo and to_remove_lo.get(-lo[0], 0) > 0:
                to_remove_lo[-lo[0]] -= 1
                heapq.heappop(lo)
            while hi and to_remove_hi.get(hi[0], 0) > 0:
                to_remove_hi[hi[0]] -= 1
                heapq.heappop(hi)

            if lo and out_val <= -lo[0]:
                balance -= 1
                to_remove_lo[out_val] = to_remove_lo.get(out_val, 0) + 1
            else:
                balance += 1
                to_remove_hi[out_val] = to_remove_hi.get(out_val, 0) + 1

        if balance > 1:
            val = -heapq.heappop(lo)
            heapq.heappush(hi, val)
            balance -= 2
        elif balance < 0:
            val = heapq.heappop(hi)
            heapq.heappush(lo, -val)
            balance += 2

        while lo and to_remove_lo.get(-lo[0], 0) > 0:
