            heapq.heappop(lo)
        while hi and to_remove_hi.get(hi[0], 0) > 0:
            to_remove_hi[hi[0]] -= 1
            heapq.heappop(hi)

        if i >= k - 1:
            if k % 2 == 1:
                res.append(float(-lo[0]))
            else:
                res.append((-lo[0] + hi[0]) / 2.0)

