class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.num_components = n
        self.history = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)
        if root_a == root_b:
            return False

        if self.rank[root_a] < self.rank[root_b]:
            root_a, root_b = root_b, root_a

        increased = (self.rank[root_a] == self.rank[root_b])
        self.parent[root_b] = root_a
        if increased:
            self.rank[root_a] += 1

        self.history.append((root_b, increased))
        self.num_components -= 1
        return True

    def snapshot(self):
        return len(self.history)

    def rollback(self, token):
        while len(self.history) > token:
            child, increased = self.history.pop()
            root = self.parent[child]
            if increased:
                self.rank[root] -= 1
            self.parent[child] = child
            self.num_components += 1

    def components(self):
        return self.num_components

