        self.root = TrieNode()

    def add(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.count += 1

    def remove(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        if node.count > 0:
            node.count -= 1
            return True
        return False

    def search(self, pattern):
        results = []
        self._search(0, self.root, [], pattern, results)
        return sorted(results)

    def _search(self, idx, node, prefix, pattern, results):
        if idx == len(pattern):
            self._collect(node, prefix, results)
            return

        char = pattern[idx]
        if char == '.':
            for c, child in node.children.items():
                prefix.append(c)
                self._search(idx + 1, child, prefix, pattern, results)
                prefix.pop()
        else:
            if char in node.children:
                prefix.append(char)
                self._search(idx + 1, node.children[char], prefix, pattern, results)
                prefix.pop()

    def _collect(self, node, prefix, results):
        if node.count > 0:
            results.append("".join(prefix))
        for c, child in node.children.items():
            prefix.append(c)
            self._collect(child, prefix, results)
            prefix.pop()
