    def __init__(self, capacity, refill_per_sec, clock):
        self.capacity = float(capacity)
        self.refill_per_sec = float(refill_per_sec)
        self.clock = clock
        self.tokens = self.capacity
        self.last_time = clock()

    def take(self, n=1):
        if n > self.capacity:
            return False

        now = self.clock()
        elapsed = max(0.0, now - self.last_time)
        if elapsed > 0:
            self.tokens += elapsed * self.refill_per_sec
            if self.tokens > self.capacity:
                self.tokens = self.capacity
            self.last_time = now

        if self.tokens >= n:
            self.tokens -= n
            return True
        return False
