import threading

def transfer_all(accounts, ops):
    locks = [threading.Lock() for _ in accounts]

    def do_transfer(src, dst, amount):
        if src < dst:
            first_lock, second_lock = locks[src], locks[dst]
        elif src > dst:
            first_lock, second_lock = locks[dst], locks[src]
        else:
            return

        with first_lock:
            with second_lock:
                if accounts[src] >= amount:
                    accounts[src] -= amount
                    accounts[dst] += amount

    threads = [threading.Thread(target=do_transfer, args=(s, d, a)) for s, d, a in ops]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    return accounts
