  const typeB = Object.prototype.toString.call(b);
  if (typeA !== typeB) return false;

  // Cycle detection for reference types that can contain references
  if (typeA === '[object Object]' || Array.isArray(a) || typeA === '[object Map]' || typeA === '[object Set]') {
