async function* chunkAsync(source, size) {
  const iterator = (source[Symbol.asyncIterator] || source[Symbol.iterator]).call(source);
  try {
    while (true) {
      const chunk = [];
      for (let i = 0; i < size; i++) {
        const { done, value } = await iterator.next();
        if (done) break;
        chunk.push(value);
      }
      if (!chunk.length) break;
      yield chunk;
