function toposortTasks(tasks) {
  const taskNames = Object.keys(tasks);
  const inDegree = {};
  const dependents = {};

  for (const name of taskNames) {
    inDegree[name] = tasks[name].deps.length;
    dependents[name] = [];
  }

  for (const name of taskNames) {
    for (const dep of tasks[name].deps) {
      if (!tasks[dep]) throw new Error(`Unknown dependency: ${dep}`);
      dependents[dep].push(name);
    }
  }

  const results = {};
  let firstError = null;
  const pending = new Set(taskNames);
  const queue = taskNames.filter(n => inDegree[n] === 0);
  const skipped = new Set();

  async function run() {
    while (queue.length > 0) {
      const batch = queue.filter(n => !skipped.has(n));
      queue.length = 0;

      await Promise.all(batch.map(async name => {
        try {
          const depValues = {};
          for (const dep of tasks[name].deps) {
            depValues[dep] = results[dep];
          }
          const val = await tasks[name].run(depValues);
          results[name] = val;
          pending.delete(name);

          for (const dependent of dependents[name]) {
            inDegree[dependent]--;
            if (inDegree[dependent] === 0) queue.push(dependent);
          }
        } catch (e) {
          firstError = firstError || e;
          pending.delete(name);
          skipped.add(name);

          const stack = [...dependents[name]];
          while (stack.length > 0) {
            const n = stack.pop();
            if (!skipped.has(n)) {
              skipped.add(n);
              stack.push(...dependents[n]);
            }
          }
        }
      }));
    }
  }

  await run();

  const remaining = [...pending].filter(n => !skipped.has(n));
  if (remaining.length > 0) {
    throw new Error('cycle detected');
  }

  if (firstError) throw firstError;
  return results;
}

module.exports = toposortTasks;
