export class Bus<E extends Record<string, unknown>> {
  private listeners = new Map<keyof E, Array<(payload: unknown) => void>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    const list = this.listeners.get(k);
    if (!list) {
      this.listeners.set(k, [fn as (payload: unknown) => void]);
      return () => {};
    }
    list.push(fn as (payload: unknown) => void);
    return () => {
      const idx = list.indexOf(fn as (payload: unknown) => void);
      if (idx !== -1) list.splice(idx, 1);
    };
  }

  emit<K extends keyof E>(k: K): void;
  emit<K extends keyof E>(k: K, payload: Exclude<E[K], void>): void;
  emit<K extends keyof E>(k: K, payload?: unknown): void {
    const list = this.listeners.get(k);
    if (list) {
      for (const fn of list) {
        fn(payload);
      }
    }
  }
}
