export function curry<F extends (...args: any[]) => any>(fn: F): Curry<F> {
  return ((...args: any[]) => {
    if (args.length >= fn.length) {
      return fn(...args);
    }
    const collected = args;
    return curry((...rest: any[]) => {
      const combined = [...collected, ...rest];
      if (combined.length >= fn.length) {
        return fn(...combined.slice(0, fn.length));
      }
      // If not enough, we need to keep collecting. But the type expects a function expecting the rest.
    });
  }) as Curry<F>;
