type ExtractParams<S extends string> = 
  S extends `${string}:${infer P}/${infer R}` ? [P, ...ExtractParams<`/${R}`>] :
  S extends `${string}:${infer P}` ? [P] :
  [];

type ParamsToObject<P extends string[]> = { [K in P[number]]: string } & Record<string, never>;

type RouteFn<P extends string[]> = 
  P extends [] ? () => string : 
  (params: ParamsToObject<P>) => string;

export type DefineRoutes<T extends Record<string, string>> = {
  [K in keyof T]: RouteFn<ExtractParams<T[K]>>;
};

function extractParams(template: string): string[] {
  const params: string[] = [];
  let remaining = template;
  while (remaining.includes(':')) {
    const idx = remaining.indexOf(':');
    const nextSlash = remaining.indexOf('/', idx + 1);
    const endIdx = nextSlash === -1 ? remaining.length : nextSlash;
    params.push(remaining.slice(idx + 1, endIdx));
    remaining = remaining.slice(endIdx);
  }
  return params;
}

export function defineRoutes<Routes extends Record<string, string>>(routes: Routes): DefineRoutes<Routes> {
  const result = {} as DefineRoutes<Routes>;
  for (const [name, template] of Object.entries(routes)) {
    const params = extractParams(template);
    if (params.length === 0) {
      result[name] = (() => template) as any;
    } else {
      result[name] = ((paramsObj: Record<string, string>) => {
        let path = template;
        for (const [key, value] of Object.entries(paramsObj)) {
          path = path.replace(`:${key}`, value);
        }
        return path;
      }) as any;
    }
  }
  return result;
}
