export type DeepPartial<T> = {
  [P in keyof T]?: T[P] extends object
    ? T[P] extends Function | readonly any[]
      ? T[P]
      : DeepPartial<T[P]>
    : T[P];
};

export function applyPatch<T extends object>(base: T, patch: DeepPartial<T>): T {
  const result = Array.isArray(base) ? [...(base as unknown[])] : { ...base };

  for (const key of Object.keys(patch)) {
    const patchValue = (patch as any)[key];

    if (patchValue === undefined) continue;

    const baseValue = (base as any)[key];

    if (Array.isArray(patchValue)) {
      (result as any)[key] = patchValue;
    } else if (typeof patchValue === 'object' && patchValue !== null) {
      const baseObj = Array.isArray(baseValue) ? [] : (baseValue ?? {});
      (result as any)[key] = applyPatch(baseObj, patchValue as any);
    } else {
      (result as any)[key] = patchValue;
    }
  }

  return result as T;
}
